const { topic_id, topic_name, count } = $input.first().json;

const prompt = `Generate ${count || 30} quiz cards for the topic: "${topic_name}".

For each item, provide:
1. correct_answer: The exact name (e.g., "Monkey D. Luffy")
2. wikipedia_slug: URL-friendly version for Wikipedia API
   - Replace spaces with underscores
   - Add disambiguation if needed in parentheses
   - Examples: "Monkey_D._Luffy", "Sanji_(One_Piece)", "Nami_(One_Piece)"

Return ONLY valid JSON:
{
  "cards": [
    {
      "correct_answer": "Monkey D. Luffy",
      "wikipedia_slug": "Monkey_D._Luffy"
    },
    {
      "correct_answer": "Sanji",
      "wikipedia_slug": "Sanji_(One_Piece)"
    }
  ]
}`;

return {
  topic_id,
  topic_name,
  prompt
};

const claudeResponse = $input.first().json.content[0].text;
const { topic_id, topic_name } = $node['Build Claude Prompt'].json;

// Extract JSON from Claude response
const jsonMatch = claudeResponse.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  throw new Error('No JSON found in Claude response');
}

const parsed = JSON.parse(jsonMatch[0]);

// Output each card as separate item for parallel processing
return parsed.cards.map((card, index) => ({
  json: {
    topic_id,
    topic_name,
    card_id: `${topic_id}_${String(index + 1).padStart(3, '0')}`,
    correct_answer: card.correct_answer,
    wikipedia_slug: card.wikipedia_slug
  }
}));

const wikiResponse = $input.first().json;
const cardData = $node['Parse Claude Response'].item($item.index).json;

let imageFilename = null;

// Get images from Wikipedia page
if (wikiResponse.query && wikiResponse.query.pages && wikiResponse.query.pages.length > 0) {
  const page = wikiResponse.query.pages[0];

  if (page.images && page.images.length > 0) {
    // Find the most relevant image (usually matches character name)
    const characterName = cardData.correct_answer.replace(/\s+/g, '_');

    // Try to find image matching character name
    let matchingImage = page.images.find(img => {
      const title = img.title.replace('File:', '');
      return title.includes(characterName) || 
             title.includes(cardData.correct_answer.split(' ')[0]) ||
             title.toLowerCase().includes('face') ||
             title.toLowerCase().includes(characterName.toLowerCase());
    });

    // Fallback to first non-icon image
    if (!matchingImage) {
      matchingImage = page.images.find(img => {
        const title = img.title.toLowerCase();
        return !title.includes('icon') && 
               !title.includes('symbol') && 
               !title.includes('flag') &&
               (title.endsWith('.jpg') || title.endsWith('.png') || title.endsWith('.jpeg'));
      });
    }

    if (matchingImage) {
      imageFilename = matchingImage.title.replace('File:', '').replace(/ /g, '_');
    }
  }
}

if (!imageFilename) {
  // Fallback: use character name as filename
  imageFilename = cardData.correct_answer.replace(/\s+/g, '_') + '.png';
}

return {
  json: {
    ...cardData,
    image_filename: imageFilename
  }
};

const response = $input.first();
const cardData = $node['Extract Image Filename'].item($item.index).json;

// Get the final URL after redirects
let imageUrl = response.headers.location || '';

// If no location header, build URL from filename
if (!imageUrl) {
  const filename = cardData.image_filename;
  // Try common Wikimedia paths
  const firstChar = filename.charAt(0).toLowerCase();
  const secondChar = filename.charAt(1).toLowerCase();
  imageUrl = `https://upload.wikimedia.org/wikipedia/en/${firstChar}/${firstChar}${secondChar}/${filename}`;
}

return {
  json: {
    topic_id: cardData.topic_id,
    topic_name: cardData.topic_name,
    card_id: cardData.card_id,
    image_url: imageUrl,
    correct_answer: cardData.correct_answer
  }
};
